// Generates the Palisade route map from the vendored OpenAPI spec: each
// operationId → its HTTP method and path template. This is the runtime
// companion to the generated `operations` types (openapi-typescript emits
// types only), used by `PalisadeApi.call(operationId, …)` to resolve the
// request. Regenerated by `npm run typegen`, so it never drifts from the spec.
//
// Output: src/generated/palisade-routes.ts

import { readFileSync, writeFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import { dirname, join } from 'node:path'
import { parse } from 'yaml'

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..')
const spec = parse(
  readFileSync(join(ROOT, 'openapi/palisade-api.yaml'), 'utf8'),
)

const METHODS = ['get', 'post', 'put', 'patch', 'delete']
const entries = []
for (const [path, item] of Object.entries(spec.paths ?? {})) {
  for (const method of METHODS) {
    const op = item[method]
    if (op?.operationId === undefined) continue
    // The operation's first OpenAPI tag is its Palisade permission scope, used
    // for tag-based auth routing (option b). Fall back to the id if untagged.
    const scope = op.tags?.[0] ?? op.operationId
    entries.push([op.operationId, method.toUpperCase(), path, scope])
  }
}
entries.sort((a, b) => a[0].localeCompare(b[0]))

const scopes = [...new Set(entries.map(([, , , scope]) => scope))].sort(
  (a, b) => a.localeCompare(b),
)
const scopeUnion = scopes
  .map((scope) => `  | ${JSON.stringify(scope)}`)
  .join('\n')

const body = entries
  .map(
    ([id, m, p, scope]) =>
      `  ${JSON.stringify(id)}: { method: '${m}', path: '${p}', scope: ${JSON.stringify(scope)} },`,
  )
  .join('\n')

const out = `/**
 * This file was auto-generated by scripts/gen-palisade-routes.mjs.
 * Do not make direct changes to the file. Regenerate with \`npm run typegen\`.
 *
 * Each Palisade operationId → its HTTP method, path template, and permission
 * scope (the runtime companion to the \`operations\` types in ./palisade.js).
 * Consumed by \`PalisadeApi.call\`.
 */

/** A Palisade permission scope (the operation's OpenAPI tag). */
export type PalisadeScope =
${scopeUnion}

export interface PalisadeRoute {
  readonly method: 'GET' | 'POST' | 'PUT' | 'PATCH' | 'DELETE'
  readonly path: string
  readonly scope: PalisadeScope
}

export const PALISADE_ROUTES = {
${body}
} as const satisfies Record<string, PalisadeRoute>
`

writeFileSync(join(ROOT, 'src/generated/palisade-routes.ts'), out)
console.log(`palisade-routes.ts: ${entries.length} operations`)
